    if not PY2 and hasattr(inspect, 'signature'):
        try:
            spec = inspect.signature(func)
            params = list(spec.parameters.values())

            # Count different parameter types
            pos_count = 0  # POSITIONAL_ONLY or POSITIONAL_OR_KEYWORD without default
            kwonly_count = 0  # KEYWORD_ONLY parameters

            for param in params:
                if param.kind in (inspect.Parameter.POSITIONAL_ONLY, 
                                  inspect.Parameter.POSITIONAL_OR_KEYWORD):
                    pos_count += 1
                elif param.kind == inspect.Parameter.KEYWORD_ONLY:
                    kwonly_count += 1

            required_names = set()
            # Determine required names from positional params without defaults
            n_params = len(params)
            idx = 0
            for i, param in enumerate(params):
                if param.kind in (inspect.Parameter.POSITIONAL_ONLY, 
                                  inspect.Parameter.POSITIONAL_OR_KEYWORD):
                    if param.default is inspect.Parameter.empty:
                        required_names.add(param.name)
                    idx += 1

            # Also include required keyword-only args
            for param in params:
                if param.kind == inspect.Parameter.KEYWORD_ONLY:
                    if param.default is inspect.Parameter.empty:
                        required_names.add(param.name)

            max_n = pos_count + kwonly_count
            required_n = len(required_names)

            _cache[func] = (required_names, required_n, max_n)
            return _cache[func]
